nextflow_process {

    name "Test Process QUILT"
    script "../main.nf"
    process "QUILT_QUILT"

    tag "modules"
    tag "modules_nfcore"
    tag "quilt/quilt"
    tag "quilt"
    tag "bcftools/query"
    tag "gawk"

    config "./nextflow.config"

    test("homo_sapiens - bam, hap, legend, posfile, phasefile, map - fasta") {
        setup {
            run("BCFTOOLS_QUERY") {
                script "../../../bcftools/query/main.nf"
                process {
                    """
                    input[0] = [
                        [id: 'NA12878'],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi', checkIfExists: true)
                    ]
                    input[1] = []
                    input[2] = []
                    input[3] = []
                    """
                }
            }

            run("GAWK", alias: "GAWK_NAME") {
                script "../../../gawk/main.nf"
                process {
                    """
                    program  = channel.of('BEGIN{print "NA12878"} {print}').collectFile(name: 'program.txt', newLine: true)
                    input[0] = BCFTOOLS_QUERY.out.output.map { meta, file -> tuple(meta, file, "phasefile.name.txt") }
                    input[1] = program
                    input[2] = false
                    """
                }
            }
        }

        when {
            params{
                quilt_args = "--save_prepared_reference=TRUE --make_plots=TRUE --seed=1"
                bcftools_query_args = "-f '[%GT]\\n' -r chr22"
                bcftools_query_suffix = "phasefile.txt"
            }
            process {
                """
                input[0] = channel.of([
                    [ id:'NA12878', chr:'chr22' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai', checkIfExists: true),
                    [], [],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.hap.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.legend.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.posfile', checkIfExists: true),
                ])
                .combine(GAWK_NAME.out.output.map{ it[1] })
                .combine(channel.of([
                    [], "chr22", "16570000", "16610000", "100", "10000",
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.stitch.map", checkIfExists:true)
                ]))
                input[1] = [
                    [id: 'GRCh38'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["plots", "rdata"], variantsMD5Keys:["vcf"])).match() }
            )
        }
    }

    test("homo_sapiens - bam, hap, legend, posfile, genfile, map - fasta") {
        setup {
            run("BCFTOOLS_QUERY") {
                script "../../../bcftools/query/main.nf"
                process {
                    """
                    input[0] = [
                        [id: 'NA12878'],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi', checkIfExists: true)
                    ]
                    input[1] = []
                    input[2] = []
                    input[3] = []
                    """
                }
            }

            run("GAWK", alias: "GAWK_NAME") {
                script "../../../gawk/main.nf"
                process {
                    """
                    program = channel.of(
                        '''BEGIN { OFS="\\t"; print "NA12878" }
                        {
                            for (i=1; i<=NF; i++) {
                                if (\$i ~ /\\\\./) {
                                    \$i = "NA"
                                } else {
                                    n = split(\$i, a, /[\\\\/|]/)
                                    if (n != 2)
                                        \$i = "NA"
                                    else if (a[1] == 0 && a[2] == 0)
                                        \$i = 0
                                    else if (a[1] == a[2])
                                        \$i = 2
                                    else
                                        \$i = 1
                                }
                            }
                            print
                        }'''
                    ).collectFile(name: 'program.txt', newLine: true)

                    input[0] = BCFTOOLS_QUERY.out.output.map { meta, file -> tuple(meta, file, "genfile.name.txt") }
                    input[1] = program
                    input[2] = false
                    """
                }
            }
        }

        when {
            params{
                quilt_args = "--save_prepared_reference=TRUE --seed=1"
                bcftools_query_args = "-f '[%GT]\\n' -r chr22"
                bcftools_query_suffix = "genfile.txt"
            }
            process {
                """
                input[0] = channel.of([
                    [ id:'NA12878', chr:'chr22' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai', checkIfExists: true),
                    [], [],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.hap.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.legend.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.posfile', checkIfExists: true),
                    []
                ])
                .combine(GAWK_NAME.out.output.map{ it[1] })
                .combine(channel.of([
                    "chr22", "16570000", "16610000", "100", "10000",
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.stitch.map", checkIfExists:true)
                ]))
                input[1] = [
                    [id: 'GRCh38'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["rdata"], variantsMD5Keys:["vcf"])).match() },
                { assert new File(new File(process.out.vcf[0][1]).parent, '.command.err').text.contains('Final imputation dosage accuracy for sample NA12878') }
            )
        }
    }

    test("QUILT - stub") {
        options '-stub'
        when {
            params{
                quilt_args = "--save_prepared_reference=TRUE --make_plots=TRUE"
            }
            process {
                """
                input[0] = channel.of([
                    [ id:'NA12878', chr:'chr22' ],
                    [], [], [], [], [], [], [], [],
                    [], "chr22", "16570000", "16610000", "100", "10000", []
                ])
                input[1] = [
                    [id: 'GRCh38'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("QUILT no optional files") {
        when {
            params{
                quilt_args = "--seed=1"
            }
            process {
                """
                input[0] = [
                    [ id:'test', chr:'chr22' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai', checkIfExists: true),
                    [], [],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.hap.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.legend.gz', checkIfExists: true),
                    [], [], [],
                    "chr22", "16570000", "16610000", "100", "10000",
                    []
                ]
                input[1] = [[id: null], [], []]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, variantsMD5Keys:["vcf"])).match() }
            )
        }
    }

    test("QUILT with bamlist and renaming") {
        when {
            params{
                quilt_args = "--seed=1"
            }
            process {
                """
                bamlist = channel.of(
                    "NA12878.chr21_22.1X.bam",
                ).collectFile(name : 'bamlist.txt', newLine : true)

                bamnames = channel.of(
                    "Mysample1",
                ).collectFile(name : 'bamnames.txt', newLine : true)

                ch_input = channel.of([
                    [ id:'test', chr:'chr22' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/NA12878.chr21_22.1X.bam.bai', checkIfExists: true)
                ])
                .combine(bamlist)
                .combine(bamnames)
                .combine(channel.of([
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.hap.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr22.legend.gz', checkIfExists: true),
                    [], [], [],
                    "chr22", "16570000", "16610000", "100", "10000",
                    []
                ]))

                input[0] = ch_input
                input[1] = [[id: null], [], []]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, variantsMD5Keys:["vcf"])).match() },
                { assert path(process.out.vcf[0][1]).vcf.header.getGenotypeSamples() == ["Mysample1"] }
            )
        }
    }

}

process {
    // More than 1 cpu may lead to different md5sum
    resourceLimits = [
        cpus: 1
    ]
    withName: QUILT_QUILT {
        ext.args = { "${params.quilt_args}" }
    }
    withName: BCFTOOLS_QUERY {
        ext.args   = { "${params.bcftools_query_args}" }
        ext.suffix = { "${params.bcftools_query_suffix}" }
    }
}
